<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {scheduleApi} from '../schedules'
const props=defineProps<{homeworkId:number}>()
const emit=defineEmits<{busy:[value:boolean];dirty:[value:boolean]}>()
const students=ref<any[]>([]),loading=ref(false),saving=ref(0),error=ref(''),message=ref(''),search=ref(''),filter=ref('')
const statuses=[['pending','Pending'],['submitted','Submitted'],['missing','Missing'],['reviewed','Reviewed']]
const visible=computed(()=>students.value.filter(s=>(!filter.value||s.saved===filter.value)&&(s.full_name+' '+s.login_id).toLowerCase().includes(search.value.toLowerCase().trim())))
watch(students,()=>emit('dirty',students.value.some(s=>s.status!==s.saved)),{deep:true})
async function refresh(){if(students.value.some(s=>s.status!==s.saved)&&!window.confirm('Discard unsaved statuses and refresh?'))return;await load()}
async function load(){loading.value=true;error.value='';try{const r=await scheduleApi(`teacher/homework/${props.homeworkId}/progress`);students.value=r.students.map((s:any)=>({...s,saved:s.status}))}catch(e){error.value=e instanceof Error?e.message:'Unable to load progress.'}finally{loading.value=false}}
async function save(s:any){saving.value=s.id;emit('busy',true);error.value='';message.value='';try{const r=await scheduleApi(`teacher/homework/${props.homeworkId}/progress/${s.id}`,'PUT',{status:s.status,version:s.version});s.saved=r.status;s.version=r.version;message.value=`Saved ${s.full_name}’s status.`}catch(e){error.value=e instanceof Error?e.message:'Unable to save progress.'}finally{saving.value=0;emit('busy',false)}}
onMounted(load)
</script>
<template><section class="homework-tracking"><p class="muted">Record work received in class. Students and linked parents can see saved statuses.</p><p v-if="loading" role="status">Loading students…</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><div class="tracking-summary"><span v-for="[value,label] in statuses" :key="value">{{label}} <strong>{{students.filter(s=>s.saved===value).length}}</strong></span></div><div class="tracking-filters"><label>Find a student<input v-model="search" type="search" placeholder="Name or student ID"></label><label>Status<select v-model="filter"><option value="">All statuses</option><option v-for="[value,label] in statuses" :key="value" :value="value">{{label}}</option></select></label><button type="button" class="secondary" :disabled="loading||!!saving" @click="refresh">Refresh</button></div><p v-if="!loading&&!error&&!visible.length">No students match.</p><div v-for="s in visible" :key="s.id" class="tracking-student"><div><strong>{{s.full_name}}</strong><small>{{s.login_id}}</small></div><label><span class="tracking-sr">Status for {{s.full_name}}</span><select v-model="s.status" :disabled="!!saving"><option v-for="[value,label] in statuses" :key="value" :value="value">{{label}}</option></select></label><button type="button" :disabled="!!saving||s.status===s.saved" @click="save(s)">{{saving===s.id?'Saving…':'Save'}}</button></div></section></template>
<style scoped>
.tracking-summary{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.tracking-summary span{background:#eef4f0;padding:8px 10px;border-radius:8px;font-size:13px}.tracking-filters{display:flex;align-items:end;flex-wrap:wrap;gap:12px}.tracking-filters label{flex:1;min-width:140px}.homework-tracking input,.homework-tracking select{width:100%;font:inherit;font-size:16px;padding:10px;border:1px solid #bccfc5;border-radius:8px;background:white;color:#243e33}.homework-tracking label{margin:0}.homework-tracking button{width:auto;margin:0;min-height:44px;padding:10px 14px;font-size:14px}.tracking-student{display:grid;grid-template-columns:minmax(0,1fr) 150px auto;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid #dce5df;font-size:15px}.tracking-student small{display:block;color:#60736e;font-size:12px;margin-top:4px}.tracking-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:480px){.tracking-student{grid-template-columns:minmax(0,1fr) auto;gap:8px}.tracking-student>div{grid-column:1/-1}.tracking-student label{width:100%}}
</style>
